// FindTranslation retrieves a single record by ID with an executor.
// If selectCols is empty Find will return all columns.
func FindTranslation(ctx context.Context, exec boil.ContextExecutor, iD string, selectCols ...string) (*Translation, error) {
	translationObj := &Translation{}

	sel := "*"
	if len(selectCols) > 0 {
		sel = strings.Join(strmangle.IdentQuoteSlice(dialect.LQ, dialect.RQ, selectCols), ",")
	}
	query := fmt.Sprintf(
		"select %s from \"translations\" where \"id\"=$1", sel,
	)

	q := queries.Raw(query, iD)

	err := q.Bind(ctx, exec, translationObj)
	if err != nil {
		if errors.Is(err, sql.ErrNoRows) {
			return nil, sql.ErrNoRows
		}
		return nil, errors.Wrap(err, "core: unable to select from translations")
	}

	return translationObj, nil
}

